{
  "name": "opencode-cli-enforcer",
  "version": "3.1.0",
  "description": "OpenCode v2 plugin bridging Claude Code as a first-class model provider via the Claude Agent SDK",
  "type": "module",
  "exports": {
    ".": "./src/index.ts"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "claude",
    "claude-code",
    "claude-agent-sdk",
    "provider"
  ],
  "engines": {
    "node": ">=20"
  },
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  },
  "author": "lleontor705",
  "repository": {
    "type": "git",
    "url": "https://github.com/lleontor705/opencode-cli-enforcer.git"
  },
  "files": [
    "src",
    "README.md",
    "CHANGELOG.md",
    "LICENSE"
  ],
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "node --import tsx --test tests/**/*.test.ts tests/int-agy.mjs"
  },
  "dependencies": {
    "@anthropic-ai/claude-agent-sdk": "^0.3.293",
    "@modelcontextprotocol/sdk": "^1.29.0",
    "@opencode/plugin": "^2.0.26",
    "cc-session-io": "^0.4.0"
  },
  "devDependencies": {
    "@types/node": "^24.13.2",
    "tsx": "^4.22.4",
    "typescript": "^5.7.0"
  }
}
